"""全量复核收尾：覆盖359题，14个无下载题单列，不自动接入。"""
import json,datetime,hashlib
from pathlib import Path
from collections import Counter

def coverage(audited,expected):
 assert len(audited)==len(set(audited))==len(expected) and set(audited)==set(expected),'逐题覆盖不完整或重复'
def coverage_examples():
 coverage([1,2,3],{1,2,3})
 for bad in ([1,2],[1,1,3],[1,2,4]):
  try:coverage(bad,{1,2,3})
  except AssertionError:pass
  else:raise AssertionError('漏题/重复/错题号未拦截')
 return 4
def coverage_selfcheck():
 count=coverage_examples()
 import inspect
 ns={};source=inspect.getsource(coverage).replace(' and set(audited)==set(expected)','');exec(source,ns);original=globals()['coverage'];globals()['coverage']=ns['coverage']
 try:coverage_examples()
 except AssertionError:killed=True
 else:killed=False
 finally:globals()['coverage']=original
 assert killed,'错题号放行的变异没有导致自检变红'
 return count

def run():
 progress_path=Path('collab/gmyhf-pending-progress.json');progress=json.loads(progress_path.read_text());assert progress['pending']==0;coverage_selfcheck();expected={e['global_number'] for e in progress['entries']};allnums=[];batches=[]
 paths=sorted(Path('collab').glob('gmyhf-pending-batch*-review.json'),key=lambda p:int(p.name.split('batch')[1].split('-')[0]))
 assert len(paths)==16
 for p in paths:
  doc=json.loads(p.read_text());numbers=[e['global_number'] for e in doc['entries']];allnums.extend(numbers);batches.append({'batch':int(p.name.split('batch')[1].split('-')[0]),'evidence':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'summary':doc['summary']})
 coverage(allnums,expected)
 nodata=json.loads(Path('/tmp/gmyhf-without-downloads-audit.json').read_text());assert nodata['summary']=={'checked':14,'still_without_downloads':14,'newly_available':0};assert not expected&{e['global_number'] for e in nodata['entries']};Path('collab/gmyhf-without-downloads-review.json').write_text(json.dumps(nodata,ensure_ascii=False,indent=2)+'\n')
 progress.update(review_complete=True,reviewed_downloadable=len(allnums),without_downloads_checked=14,without_downloads_evidence='collab/gmyhf-without-downloads-review.json');progress_path.write_text(json.dumps(progress,ensure_ascii=False,indent=2)+'\n')
 held_reasons=dict(Counter(e['reason'] for e in progress['entries'] if e['status']=='review_hold'));assert sum(held_reasons.values())==progress['review_hold']
 totalpairs=sum(b['summary']['pairs'] for b in batches);result={'finished_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'原未接入359份可下载题逐题复核完成；另实时核查14份无下载题。完成复核不表示所有答案正确或所有题已接入。','summary':{'reviewed_downloadable':len(allnums),'review_passed':progress['review_passed'],'review_hold':progress['review_hold'],'pending':0,'pairs':totalpairs,'without_downloads_checked':14,'still_without_downloads':14,'activated_problems':0},'batch_evidence':batches,'held_original_admission_reasons':held_reasons,'without_downloads_evidence':'collab/gmyhf-without-downloads-review.json','coverage_selfchecks':4,'coverage_mutation':{'mutation':'删去题号集合相等比较，错题号不再拦截','killed':True},'procedure':{'filename':Path(__file__).name,'source':Path(__file__).read_text(),'sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}}
 Path('collab/gmyhf-pending-final-review.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
 lines=['# 剩余课题组数据：全量逐题复核完成','',f"原未接入且可下载的359题已经全部逐题复核，共{totalpairs}对数据；{progress['review_passed']}题通过本轮全部验收条件，{progress['review_hold']}题保留接入、题意、数据或资源疑点，待审0题。另14题实时回读后仍无测试数据，不能验收答案。",'','本轮只补充审核证据，没有自动接入新题、回填平台答案、修改测试输入或放宽判题资源限制。保留接入疑点的题目包含答案已经一致但缺少公开题库绑定的情况；逐文件答案结论与接入结论分别记录。','', '## 批次证据','', '| 批次 | 题数 | 数据对数 | 报告 |','| --- | --- | --- | --- |']
 for b in batches:lines.append(f"| {b['batch']} | {b['summary']['problems']} | {b['summary']['pairs']} | [逐题报告](gmyhf-pending-batch{b['batch']}-review.md) |")
 labels={'not_in_catalog':'未建立本地题库绑定','contract_protected':'保留既有输入契约','no_bucket':'未确定数据目录归属','output_over_2MiB':'输出超过2MiB边界','runtime_margin':'时限余量','special_judge':'Special Judge','manual_exclusion':'人工排除'}
 lines+=['','## 保留题目的原接入排除原因','','| 原因 | 题数 |','| --- | --- |']
 for reason,count in sorted(held_reasons.items(),key=lambda x:-x[1]):lines.append('| '+labels[reason]+' | '+str(count)+' |')
 lines+=['','原接入原因与本轮逐文件答案结论分别记录，同一道题可能另有数据或题意问题。']
 lines+=['','## 后续处理入口','','优先处理有独立反例或两种算法复现的明确语义冲突，再分别处理格式约定、Special Judge协议、题库映射和资源边界。每题原因与逐文件哈希在对应报告中；未核定项保留未核定，不作为错误答案批量回填。','','已确认的问题例如：30205有11份配置计数与当前目标不符；30827有6份答案把采样点当作补给；30828有45份答案没有实现撤销自身可撤销的规则。31415与31435分别存在布尔输出和列表括号约定差异，条件模型下值一致。31033要求约21.8MB输出，现有沙箱2MiB限制保持原状。','','30548/30549只做后台构造证书核验，未声称实现新构造求解器；31381需原Special Judge协议，不能按普通答案文件核定SPJ行为。','','## 无下载数据的14题','','| 全局题号 | 实时结果 |','| --- | --- |']
 for e in nodata['entries']:lines.append(f"| {e['global_number']} | 管理员可访问，未提供测试下载链接，保留未接入 |")
 lines+=['','实时字段哈希与读取程序见[gmyhf-without-downloads-review.json](gmyhf-without-downloads-review.json)。完整进度见[gmyhf-pending-progress.json](gmyhf-pending-progress.json)，覆盖与各批证据哈希见[gmyhf-pending-final-review.json](gmyhf-pending-final-review.json)。',''];Path('collab/gmyhf-pending-final-review.md').write_text('\n'.join(lines))
 plan=Path('collab/PLAN.md');text=plan.read_text();old=next(l for l in text.splitlines() if l.startswith('| T-058 |'));new=f"| T-058 | 按批复核全部剩余课题组数据并逐批提交推送 | Done | Codex | 359题逐题复核完成：通过{progress['review_passed']}题、保留疑点{progress['review_hold']}题、待审0题；14个无下载题实时核查仍无测试数据；16批证据及后续处理入口见 `gmyhf-pending-final-review.md`，未自动接入或回填平台 |";plan.write_text(text.replace(old,new))
 triage=Path('collab/gmyhf-pending-triage.md');text=triage.read_text();marker='\n## 全量复核收尾\n'
 if marker not in text:triage.write_text(text+marker+'\n359题逐题复核完成，另14题实时核查仍无下载数据；逐题结果、保留原因与后续处理入口见[gmyhf-pending-final-review.md](gmyhf-pending-final-review.md)。\n')
 handoff=Path('collab/HANDOFF.md');text=handoff.read_text();marker='### 2026-10-24 · Codex · 剩余课题组数据逐题复核收尾'
 if marker not in text:
  addition=f"\n{marker}\n\n359题逐题复核完成，共{totalpairs}对数据；{progress['review_passed']}题通过全部验收条件，{progress['review_hold']}题保留原因，待审0题。另14题实时核查仍无下载数据。本轮未自动接入、未回填平台、未放宽沙箱；16批证据与后续处理入口见 `gmyhf-pending-final-review.md`。\n\n";handoff.write_text(text.replace('# HANDOFF · 交接日志\n','# HANDOFF · 交接日志\n'+addition,1))
 print(result['summary'])
if __name__=='__main__':run()
